<script setup>
import {ref,computed,onMounted} from 'vue'; import PublicSite from './PublicSite.vue'; import axios from 'axios'; import { LayoutDashboard,BookHeart,NotebookPen,FolderHeart,Search,Plus,ChevronDown,Menu,X,Sun,Clock,CalendarDays,Check,ArrowUpRight,Heart,MoreHorizontal,Quote,Settings,LogOut,Leaf,Bookmark,Trash2,Pin,PinOff,Command,Flower2,Compass,BookOpen, Sparkles } from 'lucide-vue-next';
const isAdmin=ref(location.pathname.startsWith('/admin'));const page=ref('Overview'),drawer=ref(false),user=ref(null),authenticated=ref(false),loading=ref(true),search=ref(''),categoryFilter=ref('All duas'),modal=ref(''),toast=ref(''),editId=ref(null),duas=ref([]),categories=ref([]),notes=ref([]),metrics=ref({duas:0,categories:0,notes:0}),stories=ref([]),schedules=ref([]),resources=ref([]),masail=ref([]),today=new Date();
const duaForm=ref({title:'',category_id:'',subcategory:'',arabic:'',transliteration:'',translation:'',reference:'',notes:'',is_favorite:false});const noteForm=ref({title:'',body:'',pinned:false});const catName=ref('');
const storyTypes=[{value:'prophet',label:'Prophet'},{value:'sahabi',label:'Sahabi / Companion'},{value:'tabi',label:'Tabi‘un'},{value:'atba_tabiin',label:'Atba‘ al-Tabi‘in'},{value:'women_sahabiyyah',label:'Women companions'},{value:'women_of_islam',label:'Women of Islam'},{value:'scholar',label:'Scholar'},{value:'other',label:'Other'}];
const resourceTypes=[{value:'islamic_link',label:'Islamic link'},{value:'video',label:'Video'},{value:'paper',label:'Paper'},{value:'journal',label:'Journal article'},{value:'book',label:'Book'},{value:'lecture',label:'Scholar speech / lecture'}];
const blankStory=()=>({title:'',slug:'',story_type:'prophet',person_name:'',era_label:'',short_story:'',life_journey:'',reason:'',full_story:'',lessons:'',sources:'',cover_url:'',is_published:false});
const blankResource=()=>({title:'',slug:'',resource_type:'islamic_link',creator:'',summary:'',url:'',cover_url:'',is_published:false,is_featured:false,published_at:''});
const blankMasala=()=>({title:'',slug:'',category:'',question:'',short_answer:'',answer:'',references:'',is_published:false});
const blankSchedule=(storyId=null)=>({story_id:storyId,starts_on:new Date().toLocaleDateString('en-CA'),ends_on:'',repeat_rule:'once',priority:10,is_active:true});
const storyForm=ref(blankStory()),resourceForm=ref(blankResource()),masalaForm=ref(blankMasala()),scheduleForm=ref(blankSchedule());
const nav=[{name:'Overview',icon:LayoutDashboard},{name:'Dua library',icon:BookHeart},{name:'Stories',icon:BookOpen},{name:'Masael',icon:Quote},{name:'Resources',icon:Compass},{name:'My notes',icon:NotebookPen},{name:'Categories',icon:FolderHeart}];
const dateLabel=new Intl.DateTimeFormat('en',{weekday:'long',month:'long',day:'numeric'}).format(today); const greeting=computed(()=>{let h=today.getHours();return h<12?'Good morning':h<17?'Good afternoon':'Good evening'});
const filteredDuas=computed(()=>duas.value.filter(d=>(categoryFilter.value==='All duas'||d.category?.name===categoryFilter.value)&&(`${d.title} ${d.translation||''} ${d.subcategory||''}`).toLowerCase().includes(search.value.toLowerCase())));
const days=['S','M','T','W','T','F','S']; const calendarCells=computed(()=>{let first=new Date(today.getFullYear(),today.getMonth(),1).getDay(),count=new Date(today.getFullYear(),today.getMonth()+1,0).getDate();return [...Array(first).fill(null),...Array.from({length:count},(_,i)=>i+1)]});
async function load(){loading.value=true;try{let b=(await axios.get('/api/bootstrap')).data;authenticated.value=b.authenticated;user.value=b.user;duas.value=b.duas;categories.value=b.categories;if(authenticated.value){let [dash,n,st,sc,re,ma]=await Promise.all([axios.get('/api/dashboard'),axios.get('/api/notes'),axios.get('/api/admin/stories'),axios.get('/api/admin/story-schedules'),axios.get('/api/admin/resources'),axios.get('/api/admin/masail')]);metrics.value=dash.data;notes.value=n.data;stories.value=st.data;schedules.value=sc.data;resources.value=re.data;masail.value=ma.data}}catch(e){console.error(e)}finally{loading.value=false}}
function syncRoute(){isAdmin.value=location.pathname.startsWith('/admin');let p=location.pathname.replace(/\/$/,'');page.value=p.endsWith('/dua')?'Dua library':p.endsWith('/notes')?'My notes':p.endsWith('/categories')?'Categories':p.endsWith('/stories')?'Stories':p.endsWith('/masael')?'Masael':p.endsWith('/resources')?'Resources':'Overview'}
async function go(n){page.value=n;drawer.value=false;let paths={'Overview':'/admin','Dua library':'/admin/dua','Stories':'/admin/stories','Masael':'/admin/masael','Resources':'/admin/resources','My notes':'/admin/notes','Categories':'/admin/categories'};history.pushState({},'',paths[n]||'/admin');syncRoute();if(n==='My notes'&&authenticated.value)notes.value=(await axios.get('/api/notes')).data}
function notify(s){toast.value=s;setTimeout(()=>toast.value='',2600)}
function newDua(){if(!authenticated.value){modal.value='login';return}editId.value=null;duaForm.value={title:'',category_id:categories.value[0]?.id||'',subcategory:'',arabic:'',transliteration:'',translation:'',reference:'',notes:'',is_favorite:false};modal.value='dua'}
function editDua(d){editId.value=d.id;duaForm.value={...d,category_id:d.category_id};modal.value='dua'}
async function saveDua(){try{let {data}=editId.value?await axios.put(`/api/duas/${editId.value}`,duaForm.value):await axios.post('/api/duas',duaForm.value);let i=duas.value.findIndex(x=>x.id===data.id);i<0?duas.value.unshift(data):duas.value.splice(i,1,data);categories.value=(await axios.get('/api/categories')).data;metrics.value.duas=duas.value.length;modal.value='';notify('Dua saved to your library')}catch(e){notify(e.response?.data?.message||'Please check the required fields')}}
async function removeDua(d){if(!confirm(`Delete “${d.title}”?`))return;await axios.delete(`/api/duas/${d.id}`);duas.value=duas.value.filter(x=>x.id!==d.id);notify('Dua removed')}
function newNote(){if(!authenticated.value){modal.value='login';return}editId.value=null;noteForm.value={title:'',body:'',pinned:false};modal.value='note'}function editNote(n){editId.value=n.id;noteForm.value={...n};modal.value='note'}
async function saveNote(){try{let {data}=editId.value?await axios.put(`/api/notes/${editId.value}`,noteForm.value):await axios.post('/api/notes',noteForm.value);let i=notes.value.findIndex(x=>x.id===data.id);i<0?notes.value.unshift(data):notes.value.splice(i,1,data);metrics.value.notes=notes.value.length;modal.value='';notify('Note saved')}catch(e){notify('Please add a note title')}}
async function removeNote(n){await axios.delete(`/api/notes/${n.id}`);notes.value=notes.value.filter(x=>x.id!==n.id);notify('Note deleted')}
async function addCategory(){if(!catName.value.trim())return;try{let {data}=await axios.post('/api/categories',{name:catName.value,icon:'✦',color:'sage'});categories.value.push(data);catName.value='';metrics.value.categories=categories.value.length;notify('Category added')}catch(e){notify(e.response?.data?.message||'Could not add category')}}
async function login(e){let f=new FormData(e.target);try{let csrf=(await axios.get('/api/csrf-token',{headers:{'Cache-Control':'no-cache'}})).data.token;axios.defaults.headers.common['X-CSRF-TOKEN']=csrf;await axios.post('/api/login',{email:f.get('email'),password:f.get('password')},{headers:{'X-CSRF-TOKEN':csrf}});modal.value='';notify('Welcome back');await load()}catch(e){notify(e.response?.data?.message||'Login failed')}}
async function logout(){await axios.post('/api/logout');authenticated.value=false;user.value=null;notify('Signed out');history.pushState({},'', '/admin');syncRoute()}
function editStory(x){editId.value=x.id;storyForm.value={...blankStory(),...x,sources:(x.sources||[]).join('\n')};modal.value='story'}
function newStory(){editId.value=null;storyForm.value=blankStory();modal.value='story'}
async function saveStory(){try{let payload={...storyForm.value,sources:storyForm.value.sources.split('\n').map(x=>x.trim()).filter(Boolean)};let {data}=editId.value?await axios.put(`/api/admin/stories/${editId.value}`,payload):await axios.post('/api/admin/stories',payload);let i=stories.value.findIndex(x=>x.id===data.id);i<0?stories.value.unshift(data):stories.value.splice(i,1,data);modal.value='';notify('Story saved')}catch(e){notify(e.response?.data?.message||'Check story fields and source links')}}
async function removeStory(x){if(!confirm(`Delete “${x.title}”? Any carousel schedule for it will also be removed.`))return;await axios.delete(`/api/admin/stories/${x.id}`);stories.value=stories.value.filter(y=>y.id!==x.id);schedules.value=schedules.value.filter(y=>y.story_id!==x.id);notify('Story deleted')}
function scheduleStory(x){let existing=schedules.value.find(y=>y.story_id===x.id);editId.value=existing?.id||null;scheduleForm.value=existing?{...existing,starts_on:String(existing.starts_on).slice(0,10),ends_on:existing.ends_on?String(existing.ends_on).slice(0,10):''}:blankSchedule(x.id);modal.value='schedule'}
function editSchedule(x){editId.value=x.id;scheduleForm.value={...x,starts_on:String(x.starts_on).slice(0,10),ends_on:x.ends_on?String(x.ends_on).slice(0,10):''};modal.value='schedule'}
async function saveSchedule(){try{let payload={...scheduleForm.value,ends_on:scheduleForm.value.ends_on||null};let {data}=editId.value?await axios.put(`/api/admin/story-schedules/${editId.value}`,payload):await axios.post('/api/admin/story-schedules',payload);let i=schedules.value.findIndex(x=>x.id===data.id);i<0?schedules.value.push(data):schedules.value.splice(i,1,data);schedules.value=(await axios.get('/api/admin/story-schedules')).data;modal.value='';notify('Carousel schedule saved')}catch(e){notify(e.response?.data?.message||'Check the schedule dates')}}
async function removeSchedule(x){if(!confirm('Remove this carousel schedule?'))return;await axios.delete(`/api/admin/story-schedules/${x.id}`);schedules.value=schedules.value.filter(y=>y.id!==x.id);notify('Schedule removed')}
function editResource(x){editId.value=x.id;resourceForm.value={...blankResource(),...x,published_at:x.published_at?String(x.published_at).slice(0,10):''};modal.value='resource'}function newResource(){editId.value=null;resourceForm.value=blankResource();modal.value='resource'}
async function saveResource(){try{let payload={...resourceForm.value,published_at:resourceForm.value.published_at||null};let {data}=editId.value?await axios.put(`/api/admin/resources/${editId.value}`,payload):await axios.post('/api/admin/resources',payload);let i=resources.value.findIndex(x=>x.id===data.id);i<0?resources.value.unshift(data):resources.value.splice(i,1,data);modal.value='';notify('Resource saved')}catch(e){notify(e.response?.data?.message||'Check the resource URL and fields')}}
async function removeResource(x){if(!confirm(`Delete “${x.title}”?`))return;await axios.delete(`/api/admin/resources/${x.id}`);resources.value=resources.value.filter(y=>y.id!==x.id);notify('Resource deleted')}
function editMasala(x){editId.value=x.id;masalaForm.value={...blankMasala(),...x};modal.value='masala'}function newMasala(){editId.value=null;masalaForm.value=blankMasala();modal.value='masala'}
async function saveMasala(){try{let {data}=editId.value?await axios.put(`/api/admin/masail/${editId.value}`,masalaForm.value):await axios.post('/api/admin/masail',masalaForm.value);let i=masail.value.findIndex(x=>x.id===data.id);i<0?masail.value.unshift(data):masail.value.splice(i,1,data);modal.value='';notify('Masael entry saved')}catch(e){notify(e.response?.data?.message||'Check masael fields')}}
async function removeMasala(x){if(!confirm(`Delete “${x.title}”?`))return;await axios.delete(`/api/admin/masail/${x.id}`);masail.value=masail.value.filter(y=>y.id!==x.id);notify('Masael entry deleted')}
onMounted(()=>{window.addEventListener('popstate',syncRoute);syncRoute();if(isAdmin.value)load();else loading.value=false});
</script>
<template><div><PublicSite v-if="!isAdmin"/><div v-else class="shell"><aside class="sidebar" :class="{open:drawer}"><div class="brand"><div class="brandmark"><Flower2 :size="20"/></div><div><b>noor<span>.</span></b><small>YOUR DAILY COMPANION</small></div><button class="close-mobile icon-btn" @click="drawer=false"><X/></button></div><div class="side-label">WORKSPACE</div><nav><button v-for="item in nav" :key="item.name" @click="go(item.name)" :class="{active:page===item.name}" class="nav-item"><component :is="item.icon" :size="18"/><span>{{item.name}}</span><span v-if="item.name==='Dua library'" class="nav-count">{{duas.length}}</span></button></nav><div class="side-label library-label">YOUR LIBRARY</div><button v-for="cat in categories.slice(0,5)" :key="cat.id" class="category-nav" @click="go('Dua library');categoryFilter=cat.name"><span class="catdot" :style="{background:cat.color==='sage'?'#84a98c':'#d8b76a'}"></span>{{cat.name}}<span>{{cat.duas_count||0}}</span></button><button class="add-cat" @click="go('Categories')">＋ Add category</button><div class="sidebar-bottom"><div class="quote-card"><Quote :size="16"/><p>“Remember Me; I will remember you.”</p><small>AL-BAQARAH 2:152</small></div><div class="user-card"><div class="avatar">{{(user?.name||'Y').slice(0,1).toUpperCase()}}</div><div class="user-copy"><b>{{user?.name||'Your space'}}</b><small>{{authenticated?'Administrator':'Personal dashboard'}}</small></div><button v-if="authenticated" class="icon-btn logout" @click="logout"><LogOut :size="16"/></button></div></div></aside><div v-if="drawer" class="scrim" @click="drawer=false"></div><main class="main"><header class="topbar"><button class="icon-btn menu-btn" @click="drawer=true"><Menu/></button><div class="crumb"><span>Workspace</span><span class="slash">/</span><b>{{page}}</b></div><div class="top-actions"><div class="date-pill"><CalendarDays :size="15"/>{{dateLabel}}</div><button class="icon-btn settings" title="Settings"><Settings :size="17"/></button><a class="admin-home-link" href="/">View website</a><button v-if="!authenticated" class="login-link" @click="modal='login'">Admin sign in</button><div v-else class="admin-account"><div class="tiny-avatar">{{(user?.name||'A').slice(0,1)}}</div><button class="signout-btn" @click="logout"><LogOut :size="15"/> Sign out</button></div></div></header><div class="content" v-if="!loading">
<section v-if="page==='Overview'"><div class="welcome-row"><div><div class="eyebrow"><Sun :size="14"/> A LITTLE SPACE FOR WHAT MATTERS</div><h1>{{greeting}}<span>, {{user?.name?.split(' ')[0]||'friend'}}.</span></h1><p class="subheading">Take a breath. Begin your day with intention.</p></div><button class="primary-btn" @click="newDua"><Plus :size="17"/> Add a dua</button></div><div class="hero-grid"><div class="hero-verse"><div class="verse-chip"><Sparkles :size="13"/> TODAY’S REMINDER</div><div class="arabic hero-arabic" dir="rtl">فَإِنَّ مَعَ الْعُسْرِ يُسْرًا</div><div class="verse-translation">“For indeed, with hardship comes ease.”</div><div class="verse-foot"><span>ASH-SHARH · 94:5</span><span class="verse-line"></span><Bookmark :size="16"/></div><div class="ornament">✳</div></div><div class="day-card"><div class="day-heading"><div><small>YOUR DAY AT A GLANCE</small><h3>{{today.toLocaleDateString('en',{month:'long'})}} {{today.getFullYear()}}</h3></div><button class="icon-btn"><MoreHorizontal/></button></div><div class="calendar"><div v-for="(d,i) in days" :key="i" class="weekday">{{d}}</div><div v-for="(d,i) in calendarCells" :key="i" class="day-cell" :class="{today:d===today.getDate()}">{{d}}</div></div><div class="day-footer"><span><span class="today-dot"></span> Today</span><span>{{dateLabel}}</span></div></div></div><div class="stats-grid"><div class="stat-card"><div class="stat-icon green"><BookHeart :size="19"/></div><div><small>DUAS IN YOUR LIBRARY</small><b>{{duas.length}}</b></div><ArrowUpRight class="stat-arrow" :size="16"/></div><div class="stat-card"><div class="stat-icon peach"><FolderHeart :size="19"/></div><div><small>COLLECTIONS</small><b>{{categories.length}}</b></div><ArrowUpRight class="stat-arrow" :size="16"/></div><div class="stat-card"><div class="stat-icon lilac"><NotebookPen :size="19"/></div><div><small>PERSONAL NOTES</small><b>{{notes.length}}</b></div><ArrowUpRight class="stat-arrow" :size="16"/></div><div class="stat-card"><div class="stat-icon gold"><Clock :size="19"/></div><div><small>DAY WELL SPENT</small><b>{{today.toLocaleDateString('en',{weekday:'long'})}}</b></div><ArrowUpRight class="stat-arrow" :size="16"/></div></div><div class="section-heading"><div><div class="eyebrow muted-eyebrow">A MOMENT OF REFLECTION</div><h2>Your dua collection</h2></div><button class="text-link" @click="go('Dua library')">Explore library <ArrowUpRight :size="15"/></button></div><div v-if="duas.length" class="dua-grid"><article class="dua-card" v-for="dua in duas.slice(0,3)" :key="dua.id"><div class="dua-meta"><span class="tag"><span class="tag-dot"></span>{{dua.category?.name||'Uncategorized'}}</span><button class="icon-btn favorite" :class="{liked:dua.is_favorite}" @click="editDua(dua)"><Heart :size="17"/></button></div><h3>{{dua.title}}</h3><div v-if="dua.arabic" class="arabic dua-arabic" dir="rtl">{{dua.arabic}}</div><p>{{dua.translation||dua.subcategory||'A personal prayer, saved for when you need it.'}}</p><div class="dua-bottom"><span>{{dua.reference||'PERSONAL COLLECTION'}}</span><button @click="editDua(dua)">Read dua <ArrowUpRight :size="14"/></button></div></article></div><div v-else class="empty-card"><div class="empty-icon"><BookOpen/></div><h3>Your first dua belongs here</h3><p>Start a collection of the words that bring you closer to what matters.</p><button class="primary-btn" @click="newDua"><Plus :size="16"/> Add your first dua</button></div><div class="lower-grid"><div class="small-panel"><div class="panel-head"><div><span class="eyebrow muted-eyebrow">CAPTURE A THOUGHT</span><h3>Recently added notes</h3></div><button class="text-link" @click="go('My notes')">All notes <ArrowUpRight :size="14"/></button></div><div v-if="notes.length" class="note-mini" v-for="n in notes.slice(0,2)" :key="n.id" @click="editNote(n)"><Pin v-if="n.pinned" :size="14"/><b>{{n.title}}</b><span>{{n.body?.slice(0,70)}}</span></div><div v-else class="quiet-empty">Your notes will find a home here.</div><button class="new-note" @click="newNote"><Plus :size="15"/> Write a note</button></div><div class="intention-card"><div class="intention-icon"><Leaf :size="18"/></div><div><small>A GENTLE REMINDER</small><p>Small, consistent acts are beloved. Give yourself credit for showing up today.</p></div><span class="intention-spark">✳</span></div></div></section>
<section v-else-if="page==='Dua library'"><div class="page-heading"><div><div class="eyebrow muted-eyebrow">WORDS TO RETURN TO</div><h1>Your dua library</h1><p class="subheading">A collection for every season of the heart.</p></div><button class="primary-btn" @click="newDua"><Plus :size="17"/> Add a dua</button></div><div class="library-tools"><div class="search-box"><Search :size="17"/><input v-model="search" placeholder="Search duas, words, themes…"/></div><select v-model="categoryFilter"><option>All duas</option><option v-for="c in categories" :key="c.id">{{c.name}}</option></select></div><div v-if="filteredDuas.length" class="dua-grid library-grid"><article class="dua-card" v-for="dua in filteredDuas" :key="dua.id"><div class="dua-meta"><span class="tag"><span class="tag-dot"></span>{{dua.category?.name||'Uncategorized'}}<template v-if="dua.subcategory"> · {{dua.subcategory}}</template></span><div><button class="icon-btn favorite" @click="editDua(dua)"><Heart :size="16"/></button><button v-if="authenticated" class="icon-btn" @click="removeDua(dua)"><Trash2 :size="15"/></button></div></div><h3>{{dua.title}}</h3><div v-if="dua.arabic" class="arabic dua-arabic" dir="rtl">{{dua.arabic}}</div><p v-if="dua.transliteration" class="translit">{{dua.transliteration}}</p><p>{{dua.translation}}</p><div class="dua-bottom"><span>{{dua.reference||'PERSONAL COLLECTION'}}</span><button @click="editDua(dua)">View details <ArrowUpRight :size="14"/></button></div></article></div><div v-else class="empty-card"><div class="empty-icon"><Search/></div><h3>No duas found</h3><p>Try another search, or add the first dua to this collection.</p><button class="primary-btn" @click="newDua"><Plus :size="16"/> Add a dua</button></div></section>
<section v-else-if="page==='My notes'"><div class="page-heading"><div><div class="eyebrow muted-eyebrow">A PLACE TO PUT IT DOWN</div><h1>Your notes</h1><p class="subheading">Thoughts, intentions, and little things worth remembering.</p></div><button class="primary-btn" @click="newNote"><Plus :size="17"/> New note</button></div><div v-if="notes.length" class="notes-grid"><article class="note-card" v-for="n in notes" :key="n.id"><div class="note-top"><span>{{new Date(n.updated_at).toLocaleDateString('en',{month:'short',day:'numeric'})}}</span><div><button class="icon-btn" @click="editNote(n)"><NotebookPen :size="15"/></button><button class="icon-btn" @click="removeNote(n)"><Trash2 :size="15"/></button></div></div><Pin v-if="n.pinned" class="pin-mark" :size="15"/><h3>{{n.title}}</h3><p>{{n.body||'An empty page is a beginning.'}}</p></article></div><div v-else class="empty-card"><div class="empty-icon"><NotebookPen/></div><h3>Make room for a thought</h3><p>Keep reflections, plans, or anything you want to remember close at hand.</p><button class="primary-btn" @click="newNote"><Plus :size="16"/> Write a note</button></div></section>
<section v-else-if="page==='Stories'"><div class="page-heading"><div><div class="eyebrow muted-eyebrow">BIOGRAPHIES · LIFE JOURNEYS · CONTEXT</div><h1>Stories of Islam</h1><p class="subheading">Write a short account, full story, life journey, context and sources. Drafts stay private.</p></div><button class="primary-btn" @click="newStory"><Plus :size="16"/> Add a story</button></div><div class="admin-content-note"><BookOpen :size="18"/><p><b>Story groups</b><span>Prophets · Sahaba · Tabi‘un · Atba‘ al-Tabi‘in · Women of Islam · Scholars</span></p></div><div class="admin-record-list"><article v-for="story in stories" :key="story.id" class="admin-content-record"><div class="record-topline"><span class="type-badge">{{storyTypes.find(x=>x.value===story.story_type)?.label||story.story_type}}</span><span :class="story.is_published?'status-published':'status-draft'">{{story.is_published?'Published':'Draft'}}</span></div><h3>{{story.title}}</h3><small>{{story.person_name}}<template v-if="story.era_label"> · {{story.era_label}}</template></small><p>{{story.short_story||story.reason||'Add a short story summary for the public listing.'}}</p><div class="record-actions"><button class="secondary-btn" @click="editStory(story)">Edit full story</button><button class="secondary-btn" @click="scheduleStory(story)"><CalendarDays :size="14"/> Schedule</button><button class="icon-btn" @click="removeStory(story)"><Trash2 :size="15"/></button></div></article><div v-if="!stories.length" class="empty-card"><h3>Start the biography collection</h3><p>Add a story with its sources, then schedule it for the daily carousel.</p><button class="primary-btn" @click="newStory"><Plus :size="15"/> Add first story</button></div></div><div class="admin-subsection"><div class="section-heading"><div><div class="eyebrow muted-eyebrow">HOMEPAGE STORY ROTATION</div><h2>Carousel schedule</h2></div></div><div v-if="schedules.length" class="schedule-list"><article v-for="item in schedules" :key="item.id" class="schedule-row"><div><b>{{item.story?.title||'Story'}}</b><small>{{item.starts_on}}<template v-if="item.ends_on"> → {{item.ends_on}}</template> · {{item.repeat_rule}}<template v-if="!item.is_active"> · Paused</template></small></div><div class="record-actions"><button class="text-link" @click="editSchedule(item)">Edit</button><button class="icon-btn" @click="removeSchedule(item)"><Trash2 :size="14"/></button></div></article></div><div v-else class="quiet-empty">No story schedule yet. Use “Schedule” on a story and choose its date and repeat pattern.</div></div></section>
<section v-else-if="page==='Resources'"><div class="page-heading"><div><div class="eyebrow muted-eyebrow">READ · WATCH · LISTEN · LEARN</div><h1>Islamic resource shelf</h1><p class="subheading">Publish links to books, videos, papers, journals and scholars’ lectures. Featured resources appear in carousel four.</p></div><button class="primary-btn" @click="newResource"><Plus :size="16"/> Add resource</button></div><div class="admin-record-list"><article v-for="item in resources" :key="item.id" class="admin-content-record"><div class="record-topline"><span class="type-badge">{{resourceTypes.find(x=>x.value===item.resource_type)?.label||item.resource_type}}</span><span :class="item.is_published?'status-published':'status-draft'">{{item.is_published?'Published':'Draft'}}</span></div><h3>{{item.title}}</h3><small>{{item.creator}}<template v-if="item.is_featured"> · Featured in carousel</template></small><p>{{item.summary}}</p><a class="record-url" :href="item.url" target="_blank" rel="noopener">{{item.url}} <ArrowUpRight :size="13"/></a><div class="record-actions"><button class="secondary-btn" @click="editResource(item)">Edit</button><button class="icon-btn" @click="removeResource(item)"><Trash2 :size="15"/></button></div></article><div v-if="!resources.length" class="empty-card"><h3>Build your resource shelf</h3><p>Add an original URL and a short note. Mark a published resource as featured to place it in the daily carousel.</p><button class="primary-btn" @click="newResource"><Plus :size="15"/> Add resource</button></div></div></section>
<section v-else-if="page==='Masael'"><div class="page-heading"><div><div class="eyebrow muted-eyebrow">QUESTIONS · SHORT ANSWERS · REFERENCES</div><h1>Masael</h1><p class="subheading">Add practical questions, concise answers and a longer referenced explanation.</p></div><button class="primary-btn" @click="newMasala"><Plus :size="16"/> Add masael</button></div><div class="admin-record-list"><article v-for="item in masail" :key="item.id" class="admin-content-record"><div class="record-topline"><span class="type-badge">{{item.category||'Masael'}}</span><span :class="item.is_published?'status-published':'status-draft'">{{item.is_published?'Published':'Draft'}}</span></div><h3>{{item.title}}</h3><small>{{item.question}}</small><p>{{item.short_answer||item.answer}}</p><div class="record-actions"><button class="secondary-btn" @click="editMasala(item)">Edit answer</button><button class="icon-btn" @click="removeMasala(item)"><Trash2 :size="15"/></button></div></article><div v-if="!masail.length" class="empty-card"><h3>No masael entries yet</h3><p>Add a question, short answer, full response and sources. Only entries marked Published appear publicly.</p><button class="primary-btn" @click="newMasala"><Plus :size="15"/> Add a question</button></div></div></section>
<section v-else><div class="page-heading"><div><div class="eyebrow muted-eyebrow">ORGANIZE YOUR REMINDERS</div><h1>Your collections</h1><p class="subheading">Create categories that make your library feel like yours.</p></div></div><div class="category-add"><div class="cat-add-icon"><FolderHeart/></div><div class="cat-add-text"><b>Create a collection</b><span>Group duas by a theme or moment in life.</span></div><input v-model="catName" @keyup.enter="addCategory" placeholder="e.g. Gratitude, Morning…"/><button class="primary-btn" @click="addCategory"><Plus :size="16"/> Add</button></div><div class="category-list"><div v-for="c in categories" :key="c.id" class="category-row"><div class="collection-icon"><span>{{c.icon||'✦'}}</span></div><div><b>{{c.name}}</b><small>{{c.duas_count||0}} duas in this collection</small></div><button class="text-link" @click="categoryFilter=c.name;go('Dua library')">Explore <ArrowUpRight :size="14"/></button></div></div></section>
</div><div v-else class="loading"><div class="loader"></div><span>Making a little space…</span></div><footer class="footer"><span>Made for slower, more intentional days.</span><span>noor<span class="brand-period">.</span> <span class="footer-dot">•</span> {{today.getFullYear()}}</span></footer></main><transition name="fade"><div v-if="modal" class="modal-backdrop" @click.self="modal=''"><div class="modal"><div class="modal-head"><div><div class="eyebrow muted-eyebrow">{{modal==='dua'?'YOUR PERSONAL COLLECTION':modal==='note'?'A THOUGHT TO KEEP':modal==='story'?'BIOGRAPHY & STORY':modal==='schedule'?'DAILY CAROUSEL SCHEDULE':modal==='resource'?'ISLAMIC RESOURCE':modal==='masala'?'MASAEL ENTRY':'ADMIN ACCESS'}}</div><h2>{{modal==='dua'?(editId?'Edit dua':'Add a dua'):modal==='note'?(editId?'Edit note':'Write a note'):modal==='story'?(editId?'Edit story':'Add a story'):modal==='schedule'?(editId?'Edit schedule':'Schedule a story'):modal==='resource'?(editId?'Edit resource':'Add resource'):modal==='masala'?(editId?'Edit masael':'Add masael'):'Welcome back'}}</h2></div><button class="icon-btn" @click="modal=''"><X/></button></div><form v-if="modal==='dua'" @submit.prevent="saveDua"><label>Dua title <span>*</span><input v-model="duaForm.title" required placeholder="A prayer for patience"/></label><div class="form-row"><label>Category <span>*</span><select v-model="duaForm.category_id" required><option value="" disabled>Select a collection</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Subcategory<input v-model="duaForm.subcategory" placeholder="Morning, travel…"/></label></div><label>Arabic<textarea v-model="duaForm.arabic" dir="rtl" placeholder="اكتب الدعاء هنا" rows="2"></textarea></label><label>Transliteration<textarea v-model="duaForm.transliteration" placeholder="Optional pronunciation guide" rows="2"></textarea></label><label>Translation<textarea v-model="duaForm.translation" placeholder="Meaning or translation" rows="3"></textarea></label><div class="form-row"><label>Source / reference<input v-model="duaForm.reference" placeholder="e.g. Qur’an 2:286"/></label><label>Personal note<input v-model="duaForm.notes" placeholder="A note to yourself"/></label></div><div class="modal-actions"><button type="button" class="secondary-btn" @click="modal=''">Cancel</button><button class="primary-btn" type="submit"><Check :size="16"/> Save dua</button></div></form><form v-else-if="modal==='note'" @submit.prevent="saveNote"><label>Note title <span>*</span><input v-model="noteForm.title" required placeholder="A small intention for today"/></label><label>Your thoughts<textarea v-model="noteForm.body" rows="7" placeholder="Write whatever is on your mind…"></textarea></label><label class="check-label"><input type="checkbox" v-model="noteForm.pinned"/> Keep this note pinned</label><div class="modal-actions"><button type="button" class="secondary-btn" @click="modal=''">Cancel</button><button class="primary-btn" type="submit"><Check :size="16"/> Save note</button></div></form><form v-else-if="modal==='story'" @submit.prevent="saveStory"><label>Story title <span>*</span><input v-model="storyForm.title" required placeholder="The life of…"/></label><div class="form-row"><label>Story group <span>*</span><select v-model="storyForm.story_type" required><option v-for="item in storyTypes" :key="item.value" :value="item.value">{{item.label}}</option></select></label><label>Person’s name<input v-model="storyForm.person_name" placeholder="Name / honorific"/></label></div><div class="form-row"><label>Era / period<input v-model="storyForm.era_label" placeholder="e.g. Early Islam"/></label><label>Cover image URL<input v-model="storyForm.cover_url" type="url" placeholder="https://…"/></label></div><label>Short story for cards and carousel<textarea v-model="storyForm.short_story" rows="3" placeholder="A concise, sourced summary…"></textarea></label><label>Historical context / why this story matters<textarea v-model="storyForm.reason" rows="3" placeholder="Context, purpose or significance…"></textarea></label><label>Life journey<textarea v-model="storyForm.life_journey" rows="5" placeholder="Key stages and events in the person’s life…"></textarea></label><label>Full story<textarea v-model="storyForm.full_story" rows="8" placeholder="Write the complete account…"></textarea></label><label>Lessons and reflections<textarea v-model="storyForm.lessons" rows="3" placeholder="Themes to reflect on…"></textarea></label><label>Sources — one URL per line<textarea v-model="storyForm.sources" rows="3" placeholder="https://reliable-source.example/page"></textarea></label><label class="check-label"><input type="checkbox" v-model="storyForm.is_published"/> Publish this story publicly</label><div class="modal-actions"><button type="button" class="secondary-btn" @click="modal=''">Cancel</button><button class="primary-btn" type="submit"><Check :size="16"/> Save story</button></div></form><form v-else-if="modal==='schedule'" @submit.prevent="saveSchedule"><label>Story to feature <span>*</span><select v-model="scheduleForm.story_id" required><option v-for="story in stories" :key="story.id" :value="story.id">{{story.title}}</option></select></label><div class="form-row"><label>First display date <span>*</span><input v-model="scheduleForm.starts_on" type="date" required/></label><label>Stop after (optional)<input v-model="scheduleForm.ends_on" type="date"/></label></div><div class="form-row"><label>Repeat pattern <select v-model="scheduleForm.repeat_rule"><option value="once">One date only</option><option value="daily">Every day</option><option value="weekly">Same weekday weekly</option><option value="monthly">Same day each month</option><option value="yearly">Same date each year</option></select></label><label>Priority (1–99)<input v-model.number="scheduleForm.priority" type="number" min="1" max="99" required/></label></div><label class="check-label"><input type="checkbox" v-model="scheduleForm.is_active"/> Schedule active</label><p class="form-hint">If more than one active schedule matches a date, the higher priority appears. Otherwise a published story is selected for the day.</p><div class="modal-actions"><button type="button" class="secondary-btn" @click="modal=''">Cancel</button><button class="primary-btn" type="submit"><Check :size="16"/> Save schedule</button></div></form><form v-else-if="modal==='resource'" @submit.prevent="saveResource"><label>Resource title <span>*</span><input v-model="resourceForm.title" required placeholder="Title of the book, talk, paper or link"/></label><div class="form-row"><label>Type <select v-model="resourceForm.resource_type"><option v-for="item in resourceTypes" :key="item.value" :value="item.value">{{item.label}}</option></select></label><label>Author / scholar / publisher<input v-model="resourceForm.creator" placeholder="Name or organization"/></label></div><label>Original URL <span>*</span><input v-model="resourceForm.url" type="url" required placeholder="https://…"/></label><div class="form-row"><label>Cover / thumbnail URL<input v-model="resourceForm.cover_url" type="url" placeholder="Optional image URL"/></label><label>Publication date<input v-model="resourceForm.published_at" type="date"/></label></div><label>What is it about?<textarea v-model="resourceForm.summary" rows="4" placeholder="A useful one-paragraph description…"></textarea></label><label class="check-label"><input type="checkbox" v-model="resourceForm.is_featured"/> Feature in carousel four</label><label class="check-label"><input type="checkbox" v-model="resourceForm.is_published"/> Publish on public resource page</label><div class="modal-actions"><button type="button" class="secondary-btn" @click="modal=''">Cancel</button><button class="primary-btn" type="submit"><Check :size="16"/> Save resource</button></div></form><form v-else-if="modal==='masala'" @submit.prevent="saveMasala"><label>Entry title <span>*</span><input v-model="masalaForm.title" required placeholder="A clear title for the question"/></label><label>Category<input v-model="masalaForm.category" placeholder="Worship, family, daily life…"/></label><label>Question<textarea v-model="masalaForm.question" rows="3" placeholder="What is being asked?"/></label><label>Short answer<textarea v-model="masalaForm.short_answer" rows="3" placeholder="A concise summary…"/></label><label>Detailed answer<textarea v-model="masalaForm.answer" rows="7" placeholder="Full answer and important qualifications…"></textarea></label><label>Sources / references<textarea v-model="masalaForm.references" rows="4" placeholder="Books, chapter/page, URLs, and other references…"></textarea></label><label class="check-label"><input type="checkbox" v-model="masalaForm.is_published"/> Publish publicly</label><p class="form-hint">Provide reliable references and have religious rulings reviewed by a qualified scholar before publication.</p><div class="modal-actions"><button type="button" class="secondary-btn" @click="modal=''">Cancel</button><button class="primary-btn" type="submit"><Check :size="16"/> Save masael</button></div></form><form v-else @submit.prevent="login"><p class="login-explain">Sign in to manage your duas, categories, and personal notes.</p><label>Email address<input name="email" type="email" required placeholder="you@example.com"/></label><label>Password<input name="password" type="password" required placeholder="Your password"/></label><div class="modal-actions"><button type="button" class="secondary-btn" @click="modal=''">Not now</button><button class="primary-btn" type="submit">Sign in <ArrowUpRight :size="15"/></button></div><small class="login-hint">Starter admin is added with php artisan db:seed.</small></form></div></div></transition><transition name="toast"><div class="toast" v-if="toast"><Check :size="16"/>{{toast}}</div></transition></div></div></template>
